func (v ResolvedValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	overlapping := types.ListValueMust(
		OverlappingType{
			basetypes.ObjectType{
				AttrTypes: OverlappingValue{}.AttributeTypes(ctx),
			},
		},
		v.Overlapping.Elements(),
	)

	if v.Overlapping.IsNull() {
		overlapping = types.ListNull(
			OverlappingType{
				basetypes.ObjectType{
					AttrTypes: OverlappingValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Overlapping.IsUnknown() {
		overlapping = types.ListUnknown(
			OverlappingType{
				basetypes.ObjectType{
					AttrTypes: OverlappingValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	var service basetypes.ObjectValue

	if v.Service.IsNull() {
		service = types.ObjectNull(
			ServiceValue{}.AttributeTypes(ctx),
		)
	}

	if v.Service.IsUnknown() {
		service = types.ObjectUnknown(
			ServiceValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Service.IsNull() && !v.Service.IsUnknown() {
		service = types.ObjectValueMust(
			ServiceValue{}.AttributeTypes(ctx),
			v.Service.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"overlapping": basetypes.ListType{
			ElemType: OverlappingValue{}.Type(ctx),
		},
		"path": basetypes.StringType{},
		"service": basetypes.ObjectType{
			AttrTypes: ServiceValue{}.AttributeTypes(ctx),
		},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"overlapping": overlapping,
			"path":        v.Path,
			"service":     service,
		})

	return objVal, diags
}

func (v ResolvedValue) Equal(o attr.Value) bool {
	other, ok := o.(ResolvedValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Overlapping.Equal(other.Overlapping) {
		return false
	}

	if !v.Path.Equal(other.Path) {
		return false
	}

	if !v.Service.Equal(other.Service) {
		return false
	}

	return true
}

